<?php require 'config/db.php';require 'includes/auth.php';require_login();$page_title='Incident Management';$q=trim($_GET['q']??'');$status=trim($_GET['status']??'');if($_SERVER['REQUEST_METHOD']==='POST'){require_role(['ADMIN','OPERATOR']);check_csrf();$action=$_POST['action']??'';if($action==='create'){ $s=$pdo->prepare('INSERT INTO incidents(incident_type,description,location,severity,status,reported_by) VALUES(?,?,?,?,?,?)');$s->execute([trim($_POST['incident_type']),trim($_POST['description']),trim($_POST['location']),$_POST['severity'],$_POST['status'],$_SESSION['user']['id']]);audit($pdo,'Incident created',$_POST['incident_type'].' at '.$_POST['location']);$_SESSION['flash']='Incident created successfully.';}elseif($action==='update'){ $s=$pdo->prepare('UPDATE incidents SET incident_type=?,description=?,location=?,severity=?,status=? WHERE id=?');$s->execute([trim($_POST['incident_type']),trim($_POST['description']),trim($_POST['location']),$_POST['severity'],$_POST['status'],(int)$_POST['id']]);audit($pdo,'Incident updated','Incident #'.(int)$_POST['id']);$_SESSION['flash']='Incident updated.';}elseif($action==='delete'){require_role(['ADMIN']);$s=$pdo->prepare('DELETE FROM incidents WHERE id=?');$s->execute([(int)$_POST['id']]);audit($pdo,'Incident deleted','Incident #'.(int)$_POST['id']);$_SESSION['flash']='Incident deleted.';}header('Location:incidents.php');exit;}$sql='SELECT i.*,u.full_name FROM incidents i JOIN users u ON u.id=i.reported_by WHERE 1=1';$args=[];if($q!==''){$sql.=' AND (i.incident_type LIKE ? OR i.location LIKE ? OR i.description LIKE ?)';$args=["%$q%","%$q%","%$q%"];}$allowed=['Open','Investigating','Resolved'];if(in_array($status,$allowed,true)){$sql.=' AND i.status=?';$args[]=$status;}$sql.=' ORDER BY i.id DESC';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();require 'includes/header.php';?><section class="panel"><?php if(can_write()):?><h2>New Incident</h2><form class="form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="create"><input name="incident_type" placeholder="Incident type" required><input name="location" placeholder="Location" required><select name="severity"><option>Low</option><option>Medium</option><option>High</option><option>Critical</option></select><select name="status"><option>Open</option><option>Investigating</option><option>Resolved</option></select><textarea name="description" class="full" placeholder="Description"></textarea><button>Save Incident</button></form><?php endif;?><div class="sectionhead"><h2>All Incidents</h2><form class="filters"><input name="q" value="<?=e($q)?>" placeholder="Search type, location..."><select name="status"><option value="">All statuses</option><?php foreach($allowed as $x):?><option <?=$status===$x?'selected':''?>><?=$x?></option><?php endforeach;?></select><button>Filter</button></form></div><div class="tablewrap"><table><tr><th>Type</th><th>Location</th><th>Severity</th><th>Status</th><th>Reported By</th><th>Actions</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['incident_type'])?></td><td><?=e($r['location'])?></td><td><span class="badge <?=strtolower($r['severity'])?>"><?=e($r['severity'])?></span></td><td><?=e($r['status'])?></td><td><?=e($r['full_name'])?></td><td><?php if(can_write()):?><a class="smallbtn" href="incident_edit.php?id=<?=$r['id']?>">Edit</a><?php endif;?> <?php if(($_SESSION['user']['role']??'')==='ADMIN'):?><form class="inline" method="post" onsubmit="return confirm('Delete this incident?')"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Delete</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section><?php require 'includes/footer.php';?>
